/* From Uiverse.io by alexreyes091 - Tags: card */
.__UIV_SCOPE__ .card {
 width: 254px;
 height: 190px;
 transform: rotate(90deg);
 background: #00BCD4;
 box-shadow: rgba(0, 0, 0, 0.12) 0px 1px 3px, rgba(0, 0, 0, 0.24) 0px 1px 2px;
 transition-duration: 1.5s;
 transition-property: width, height,transform;
}

.__UIV_SCOPE__ .card:hover {
 width: 190px;
 height: 254px;
 transform: rotate(0deg);
  /* -ms-transform:rotate(90deg);
  -webkit-transform:rotate(90deg); */
}

.__UIV_SCOPE__ .card__content {
 padding: 1rem;
 font-size: smaller;
}

.__UIV_SCOPE__ .card__date {
 color: white;
 margin-bottom: .5rem;
 font-weight: 700;
}

.__UIV_SCOPE__ .card__info {
 width: 100%;
 height: 200px;
 padding: .7rem;
 font-size: smaller;
 border-radius: 1rem;
 text-align: center;
 background-color: #fae4c3;
 color: #fae4c3;
 transition-duration: 1s;
 transition-property: color;
}

.__UIV_SCOPE__ .card__info:hover {
 color: #212121;
}
